export const CARE_GUIDE_HTML = "<!doctype html>\n<!-- The Mossgrove care guide: the page every Mossgrove app bundles for its web view (SPEC.md §Web view).\n     It loads nothing: no fonts, images or scripts from anywhere, and the policy below forbids it. -->\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'\">\n<title>Care guide</title>\n<style>\n  :root { --ink: #181C1B; --muted: #3F4946; --ground: #F7F9F7; --line: #BFC9C5; --primary: #2E5E55; --on-primary: #FFFFFF; --brass: #7A5A1C; }\n  @media (prefers-color-scheme: dark) {\n    :root { --ink: #E0E3E1; --muted: #BFC9C5; --ground: #101413; --line: #3F4946; --primary: #95D1C2; --on-primary: #003730; --brass: #EEC06E; }\n  }\n  body { margin: 0; padding: 16px; font: 16px/1.5 system-ui, sans-serif; color: var(--ink); background: var(--ground); }\n  h1 { font-size: 1.5rem; margin: 0 0 4px; }\n  h2 { font-size: 1.15rem; margin: 28px 0 8px; }\n  .number { font-family: monospace; color: var(--brass); }\n  p, li { color: var(--muted); max-width: 60ch; }\n  label { display: block; margin: 16px 0 4px; font-weight: 600; }\n  input[type=text], select { box-sizing: border-box; width: 100%; min-height: 48px; padding: 8px 12px; font: inherit;\n    color: var(--ink); background: var(--ground); border: 1px solid var(--line); border-radius: 8px; }\n  .check { display: flex; align-items: center; gap: 12px; min-height: 48px; font-weight: 400; }\n  .check input { width: 24px; height: 24px; }\n  button { min-height: 48px; padding: 0 24px; margin-top: 16px; font: inherit; font-weight: 600; border: 0; border-radius: 24px;\n    color: var(--on-primary); background: var(--primary); }\n  output { display: block; margin-top: 16px; font-weight: 600; min-height: 1.5em; }\n  a { color: var(--primary); }\n  .spacer { height: 900px; }\n</style>\n</head>\n<body>\n  <h1 id=\"web_title\" data-testid=\"web_title\">Care guide</h1>\n  <p><span class=\"number\">No. 001</span> Stoneware Mug, and everything else in the kitchen aisle.</p>\n  <p><a id=\"web_more\" data-testid=\"web_more\" href=\"#web_washing\">Jump to washing</a></p>\n\n  <h2>Ask for a reminder</h2>\n  <form id=\"web_form\" data-testid=\"web_form\">\n    <label for=\"web_name\">Your name</label>\n    <input id=\"web_name\" data-testid=\"web_name\" type=\"text\" autocomplete=\"off\">\n    <label for=\"web_frequency\">Remind me</label>\n    <select id=\"web_frequency\" data-testid=\"web_frequency\">\n      <option value=\"weekly\">Every week</option>\n      <option value=\"monthly\" selected>Every month</option>\n      <option value=\"never\">Never</option>\n    </select>\n    <label class=\"check\"><input id=\"web_agree\" data-testid=\"web_agree\" type=\"checkbox\"> Email me the guide</label>\n    <button id=\"web_submit\" data-testid=\"web_submit\" type=\"submit\">Save</button>\n    <output id=\"web_result\" data-testid=\"web_result\" aria-live=\"polite\"></output>\n  </form>\n\n  <div class=\"spacer\"></div>\n  <h2 id=\"web_washing\" data-testid=\"web_washing\">Washing</h2>\n  <p>Stoneware goes in the dishwasher. Wood does not: wipe it, dry it, and oil it once a month.</p>\n\n  <script>\n    document.getElementById('web_form').addEventListener('submit', function (event) {\n      event.preventDefault();\n      var name = document.getElementById('web_name').value.trim();\n      var how = document.getElementById('web_frequency');\n      var label = how.options[how.selectedIndex].text.toLowerCase();\n      document.getElementById('web_result').textContent = name\n        ? 'Saved, ' + name + '. We will remind you ' + label + '.'\n        : 'Enter your name first.';\n    });\n  </script>\n</body>\n</html>\n";
